class ImageLightbox{constructor(){this.overlay=null;this.isOpen=false}init(){this.createOverlay();this.bindEscape()}createOverlay(){this.overlay=document.createElement('div');this.overlay.className='lightbox-overlay';this.overlay.innerHTML='<button class="lightbox-close" aria-label="Close">&times;</button><div class="lightbox-content"><img src="" alt=""><div class="lightbox-caption"></div></div>';document.body.appendChild(this.overlay);this.overlay.addEventListener('click',e=>{if(e.target===this.overlay)this.close()});this.overlay.querySelector('.lightbox-close').addEventListener('click',()=>this.close())}bindEscape(){document.addEventListener('keydown',e=>{if(e.key==='Escape'&&this.isOpen)this.close()})}bindImages(){const chapterBody=document.getElementById('chapterBody');if(!chapterBody)return;const images=chapterBody.querySelectorAll('img:not(.parental-advisory):not([src$=".svg"])');images.forEach(img=>{if(!img.dataset.lightboxBound){img.dataset.lightboxBound='true';img.addEventListener('click',()=>this.open(img))}})}open(img){const lightboxImg=this.overlay.querySelector('.lightbox-content img');const caption=this.overlay.querySelector('.lightbox-caption');lightboxImg.src=img.src;lightboxImg.alt=img.alt||'';caption.textContent=img.alt||'';caption.style.display=img.alt?'block':'none';this.overlay.classList.add('active');this.isOpen=true}close(){this.overlay.classList.remove('active');this.isOpen=false}}export const imageLightbox=new ImageLightbox();
